// Anonymous draft-storage faults on the authorized Actions runner only.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {mkdir,mkdtemp,readFile,writeFile,symlink} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {staticOrigin} from './static-origin.mjs';
import {inventory} from '../../scripts/build-pages-artifact.mjs';
assert.equal(process.env.GITHUB_ACTIONS,'true','Use only the authorized Actions runner');
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_PACKAGE);
const artifact=resolve(process.env.PAGES_ARTIFACT),reportDir=resolve(process.env.BROWSER_REPORT);await mkdir(reportDir,{recursive:true});
const git=(...args)=>execFileSync('git',args),sha=b=>createHash('sha256').update(b).digest('hex');
const publishedMain='0fea01ce9bdeba339d6648f846bdcb966d745429',diagnostic=process.env.GITHUB_EVENT_NAME==='push';
const messages=JSON.parse(await readFile(new URL('./fixtures/short-apply-draft-status.json',import.meta.url),'utf8'));assert.equal(Object.keys(messages).length,20);
const report={head:process.env.TESTED_HEAD,base:process.env.TESTED_BASE,publishedMain,diagnostic,checkout:git('rev-parse','HEAD').toString().trim(),files:{},rows:[],startup:[],captures:[],mutations:[],external:[],limits:['Anonymous isolated browser storage only; no candidate data or delivery.','Chromium320/1280; not physical-device, offline or native-speaker certification.','DOM live-region/focus verification does not certify a screen-reader announcement.']};
if(diagnostic){assert.equal(report.checkout,report.head);assert.equal(git('rev-parse','HEAD^').toString().trim(),report.base);}else{assert.deepEqual(git('show','-s','--format=%P','HEAD').toString().trim().split(' '),[report.base,report.head]);assert.equal(git('rev-parse','HEAD^{tree}').toString().trim(),git('rev-parse',report.head+'^{tree}').toString().trim());}
for(const {path:p}of inventory(artifact)){
 const source=p.startsWith('tools/coordinator/')?'coordinator-demo/'+p.split('/').at(-1):p,b=await readFile(join(artifact,p));assert.deepEqual(b,git('show',`${report.head}:${source}`));const publishedExact=b.equals(git('show',`${publishedMain}:${source}`));if(diagnostic)assert(publishedExact,'Diagnostic inputs must equal published main: '+p);report.files[p]={source,bytes:b.length,sha256:sha(b),publishedExact};
}
assert.equal(Object.keys(report.files).length,317);
const serveRoot=await mkdtemp(join(tmpdir(),'primserv-draft-'));await symlink(artifact,join(serveRoot,'kiris-jobs'),'dir');const origin=staticOrigin(serveRoot),base='http://127.0.0.1:4173/kiris-jobs/';let browser;
const key='citronex_screening_application_v17';
async function context(width,initialMode='normal'){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block',reducedMotion:'reduce'});ctx.setDefaultTimeout(15000);
 await ctx.route('**/*',r=>{const q=r.request(),u=new URL(q.url());if(!['GET','HEAD'].includes(q.method())){report.mutations.push({method:q.method(),path:u.pathname,blocked:true});return r.abort();}if(u.origin!==new URL(base).origin){report.external.push({host:u.hostname,path:u.pathname,blocked:true});return r.abort();}return r.continue();});
 await ctx.addInitScript(initialMode=>{
  const store=window.localStorage,read=store.getItem.bind(store),write=store.setItem.bind(store),remove=store.removeItem.bind(store);
  window.__draftStorageMode=initialMode;window.__draftRead=()=>read('citronex_screening_application_v17');window.__unrelatedRead=()=>read('primserv-fixture-unrelated');write('primserv-fixture-unrelated','KEEP');
  Object.defineProperty(window,'localStorage',{configurable:true,get(){if(window.__draftStorageMode==='getter')throw new DOMException('Anonymous fixture storage access denied','SecurityError');return {getItem:read,removeItem:remove,setItem(k,v){if(window.__draftStorageMode==='quota')throw new DOMException('Anonymous fixture quota failure','QuotaExceededError');write(k,v);}};}});
 },initialMode);return ctx;
}
async function enter(page,lang){await page.goto(base+'apply/');await page.locator('#languageSearch').fill(lang);await page.locator(`[data-language="${lang}"]`).click();await page.locator('[data-recruiter="yana"]').click();await page.locator('#firstName').fill('OLD');}
async function mode(page,value){await page.evaluate(v=>window.__draftStorageMode=v,value);}
async function raw(page){return page.evaluate(()=>window.__draftRead());}
async function baseline(width,fault){
 const ctx=await context(width),page=await ctx.newPage(),warnings=[],errors=[];page.on('console',m=>{if(m.type()==='warning')warnings.push(m.text());});page.on('pageerror',e=>errors.push(e.message));
 try{
  await enter(page,'en');const before=await raw(page);assert.equal(JSON.parse(before).data.firstName,'OLD');await mode(page,fault);await page.locator('#firstName').fill('CURRENT');assert.equal(await page.locator('#firstName').inputValue(),'CURRENT');assert.equal(await raw(page),before);assert.equal(await page.evaluate(()=>document.activeElement.id),'firstName');assert.equal(await page.locator('[role="status"]').count(),0);assert(warnings.some(x=>x.startsWith('Draft save failed.')));await page.screenshot({path:join(reportDir,`baseline-${width}-${fault}.png`)});
  await mode(page,'normal');await page.locator('#firstName').fill('RECOVERED');assert.equal(JSON.parse(await raw(page)).data.firstName,'RECOVERED');await page.reload();await page.locator('[data-action="resume"]').click();assert.equal(await page.locator('#firstName').inputValue(),'RECOVERED');assert.equal(await page.evaluate(()=>window.__unrelatedRead()),'KEEP');assert.deepEqual(errors,[]);report.rows.push({width,fault,lang:'en',normalWrite:true,failedWritePreservedLastDraft:true,currentInputPreserved:true,noVisibleStatus:true,consoleWarningObserved:true,recoveredOnNextInput:true,reloadResumedRecovered:true,unrelatedPreserved:true,noDelivery:true,warnings});
 }catch(e){await page.screenshot({path:join(reportDir,`failure-${width}-${fault}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
async function status(page,lang,state){
 const n=page.locator('#draftStatus');assert.equal(await n.innerText(),messages[lang][state]);assert.equal(await n.getAttribute('data-state'),state);assert.equal(await n.getAttribute('role'),'status');assert.equal(await n.getAttribute('aria-live'),'polite');assert.equal(await n.getAttribute('aria-atomic'),'true');assert.equal(await n.getAttribute('tabindex'),null);assert.equal(await page.locator('#app #draftStatus').count(),0);assert.equal(await page.locator('html').getAttribute('lang'),lang);
 return n.evaluate(n=>{const f=n.getBoundingClientRect(),range=document.createRange();range.selectNodeContents(n);const rs=[...range.getClientRects()];return {text:n.textContent,direction:getComputedStyle(n).direction,painted:n.checkVisibility({checkOpacity:true,checkVisibilityCSS:true}),fit:document.documentElement.scrollWidth<=innerWidth+1&&n.scrollWidth<=n.clientWidth+1&&f.left>=0&&f.right<=innerWidth+1&&rs.every(r=>r.left>=f.left-1&&r.right<=f.right+1),rect:{x:f.x,y:f.y,width:f.width,height:f.height}};});
}
async function capture(page,width,lang,state){
 const active=await page.evaluate(()=>document.activeElement?.id);await page.evaluate(()=>document.fonts.ready);await page.locator('#draftStatus').evaluate(n=>n.scrollIntoView({block:'center',behavior:'instant'}));await page.waitForTimeout(200);const dom=await status(page,lang,state);assert(dom.painted&&dom.fit);if(lang==='ur')assert.equal(dom.direction,'rtl');const before=dom.rect,file=`draft-${width}-${lang}-${state}.png`;await page.locator('#draftStatus').screenshot({path:join(reportDir,file)});const after=(await status(page,lang,state)).rect;assert.deepEqual(after,before);assert.equal(await page.evaluate(()=>document.activeElement?.id),active);report.captures.push({file,width,lang,state,dom,before,after,stable:true,focusPreserved:true});
}
async function changeLanguage(page,lang){await page.locator('[data-action="language"]').click();await page.locator('#languageSearch').fill(lang);await page.locator(`[data-language="${lang}"]`).click();await page.locator('[data-recruiter="yana"]').click();}
async function feature(width,lang){
 const ctx=await context(width),page=await ctx.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{
  await enter(page,lang);await status(page,lang,'saved');await capture(page,width,lang,'saved');const before=await raw(page);assert.equal(JSON.parse(before).data.firstName,'OLD');await page.locator('#firstName').focus();await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement.id),'lastName');await page.keyboard.press('Shift+Tab');assert.equal(await page.evaluate(()=>document.activeElement.id),'firstName');
  await page.evaluate(()=>{window.__draftMutations=[];new MutationObserver(records=>window.__draftMutations.push(...records.map(r=>r.type))).observe(document.getElementById('draftStatus'),{childList:true,characterData:true,subtree:true});});
  await mode(page,'getter');await page.locator('#firstName').fill('CURRENT');assert.equal(await page.evaluate(()=>document.activeElement.id),'firstName');await status(page,lang,'failed');assert.equal(await raw(page),before);assert.equal(await page.locator('#firstName').inputValue(),'CURRENT');await capture(page,width,lang,'failed');assert.equal(await page.evaluate(()=>window.__draftMutations.length),1);
  await page.evaluate(()=>window.__draftMutations=[]);await page.locator('#firstName').fill('CURRENT2');await status(page,lang,'failed');assert.equal(await page.evaluate(()=>window.__draftMutations.length),0,'Repeated failed inputs must not repeat live text updates');await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement.id),'lastName');
  const away=lang==='en'?'ru':'en';await changeLanguage(page,away);await status(page,away,'failed');assert.equal(await page.locator('#firstName').inputValue(),'CURRENT2');await changeLanguage(page,lang);await status(page,lang,'failed');assert.equal(await raw(page),before);assert.equal(await page.locator('#firstName').inputValue(),'CURRENT2');
  await mode(page,'quota');await page.locator('#lastName').fill('QUOTA');await status(page,lang,'failed');assert.equal(await raw(page),before);assert.equal(await page.locator('#lastName').inputValue(),'QUOTA');
  // A separate reload sees only the last successful OLD draft, never failed recent edits.
  const reload=await ctx.newPage();await reload.goto(base+'apply/');await reload.locator('[data-action="resume"]').click();assert.equal(await reload.locator('#firstName').inputValue(),'OLD');assert.equal(await reload.locator('#lastName').inputValue(),'');await reload.close();
  for(const[id,value]of [['phone','+99912345678'],['citizenship','FIXTURE'],['age','30']])await page.locator('#'+id).fill(value);await page.locator('#messenger').selectOption('telegram');await page.locator('[name="gender"][value="undisclosed"]').locator('..').click();await page.locator('[data-action="next"]').click();await status(page,lang,'failed');assert.equal(await page.locator('.progress-meta strong').innerText(),'2 / 3');
  await page.locator('#location').selectOption('any');await page.locator('#stayDuration').selectOption('six');await page.locator('[name="physicalWork"][value="no"]').locator('..').click();await page.locator('[data-action="next"]').click();
  for(const f of ['performanceMetrics','fastPace','watchedVideos','understandsRole','longHours'])await page.locator(`[name="${f}"][value="no"]`).locator('..').click();await page.locator('#consent').check();await page.locator('[data-action="next"]').click();await page.locator('#arrivalTitle').waitFor();await status(page,lang,'failed');assert.equal(await page.locator('.review-sections').innerText().then(t=>t.includes('CURRENT2')),true);assert.equal(JSON.parse(await raw(page)).data.firstName,'OLD');
  await page.locator('[data-action="edit"]').click();await mode(page,'normal');await page.locator('#consent').focus();await page.keyboard.press('Space');assert(!await page.locator('#consent').isChecked());await status(page,lang,'saved');assert.equal(await page.evaluate(()=>document.activeElement.id),'consent');let recovered=JSON.parse(await raw(page));assert.equal(recovered.data.firstName,'CURRENT2');assert.equal(recovered.data.lastName,'QUOTA');assert.equal(recovered.data.consent,false);assert.equal(recovered.step,3);
  await page.evaluate(()=>window.__draftMutations=[]);await page.keyboard.press('Space');assert(await page.locator('#consent').isChecked());await status(page,lang,'saved');assert.equal(await page.evaluate(()=>window.__draftMutations.length),0,'Repeated successful writes must not repeat live text updates');assert.equal(await page.evaluate(()=>document.activeElement.id),'consent');recovered=JSON.parse(await raw(page));await page.reload();await page.locator('[data-action="resume"]').click();await status(page,lang,'saved');assert(await page.locator('#consent').isChecked());assert.deepEqual(JSON.parse(await raw(page)).data,recovered.data);assert.equal(await page.evaluate(()=>window.__unrelatedRead()),'KEEP');assert.deepEqual(errors,[]);
  report.rows.push({width,lang,status:'passed',normalWrite:true,getterDenied:true,quotaDenied:true,lastSuccessfulDraftPreserved:true,currentAnswersRetained:true,languageRoundTrip:true,independentReloadOnlyOld:true,allThreeStepsAndReviewWithoutStorage:true,nativeTabAndSpace:true,focusUnchanged:true,persistentPoliteRegion:true,repeatedTextNotReannounced:true,recoveredOnNextWrite:true,reloadResumedRecovered:true,unrelatedStoragePreserved:true,noDelivery:true});
 }catch(e){await page.screenshot({path:join(reportDir,`failure-draft-${width}-${lang}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
async function startup(width){const ctx=await context(width,'getter'),page=await ctx.newPage();try{await enter(page,'en');assert.equal(await raw(page),null);await status(page,'en','failed');assert.equal(await page.locator('#firstName').inputValue(),'OLD');await mode(page,'normal');await page.locator('#firstName').fill('RECOVERED');await status(page,'en','saved');assert.equal(JSON.parse(await raw(page)).data.firstName,'RECOVERED');report.startup.push({width,readAccessDeniedAtStartup:true,formUsable:true,recovered:true,noDelivery:true});}finally{await ctx.close();}}
try{
 await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();
 if(diagnostic){for(const width of [320,1280])for(const fault of ['getter','quota'])await baseline(width,fault);assert.equal(report.rows.length,4);report.status='BASELINE_4_RENDERED_FAULTS_NO_VISIBLE_DRAFT_STATUS';}
 else{const cases=[320,1280].flatMap(width=>Object.keys(messages).map(lang=>({width,lang})));let next=0;await Promise.all(Array.from({length:2},async()=>{while(next<cases.length){const c=cases[next++];await feature(c.width,c.lang);}}));for(const width of [320,1280])await startup(width);assert.equal(report.rows.length,40);assert.equal(report.startup.length,2);assert.equal(report.captures.length,80);report.status='PASSED_40_DRAFT_STATUS_FLOWS_2_STARTUP_FAULTS_80_FRAGMENTS';}
 assert.deepEqual(report.mutations,[]);assert.deepEqual(report.external,[]);report.applicationDeliveryAttempts=0;
}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();report.finished=new Date().toISOString();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
